pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed params: actor address and an arbitrary bytes32 hash
    function testFuzz_property(address actor, bytes32 hash) public {
        // keep actor usable and non-zero
        vm.assume(actor != address(0));

        // fund the actor so it can send 1 ether
        vm.deal(actor, 2 ether);

        // perform the call as actor sending exactly 1 ether
        vm.prank(actor);
        // call lockInGuess with 1 ether; capture whether it succeeded or reverted
        bool ok;
        try c.lockInGuess{value: 1 ether}(hash) {
            ok = true;
        } catch {
            ok = false;
        }

        // If call succeeded, then the invariant for the reference contract is:
        // guesses(actor).block > block.number at time of call completion.
        // We observe this via the auto getter for guesses (struct fields are public via mapping getter):
        // The mapping is public in original contract? (mapping(address => Guess) guesses; )
        // The contract above does not mark mapping public; but we can still observe by calling settle conditions indirectly.
        // However the problem statement allows reading public getters only. To respect that, we instead check behavior visible from public surface:
        // After successful lockInGuess, trying to settle immediately should revert (require(block.number > guesses[msg.sender].block))
        // For the reference, immediate settle by the same actor should revert (because stored block is block.number+1), but for the mutant it would allow settle to proceed (not revert) when stored block == block.number.

        if (ok) {
            // try to call settle immediately as actor; capture whether it reverts
            vm.prank(actor);
            bool settleOk;
            try c.settle() {
                settleOk = true;
            } catch {
                settleOk = false;
            }

            // Assert: for the correct contract, immediate settle must revert (settleOk == false).
            // The mutant that stored block.number will allow settleOk == true for at least some inputs (when block.number > guesses.block condition becomes true immediately), causing this assertion to fail.
            assertTrue(!settleOk);
        } else {
            // If lockInGuess reverted (e.g., because actor already had a guess), then the invariant about behaviour after a successful call is vacuously true; simply assert true via a benign observation of the contract: address(c).balance >= 1 ether
            // We must still produce exactly one assert in all paths; since above path has an assert, here we produce an assert that always holds for the reference: contract balance remained at least 1 ether after setUp.
            assertTrue(address(c).balance >= 1 ether);
        }
    }
}

