    function testFuzz_property(address actor, bytes32 guess) public {
        // Keep actor non-zero and not the contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Fund the actor so they can send 1 ether
        vm.deal(actor, 1 ether);

        // Actor calls lockInGuess with 1 ether attached
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Immediately after lockInGuess returns, read the stored block number for the actor via the public getter
        // The struct Guess has members (block, guess); Solidity will generate a getter guesses(address) returning (uint256, bytes32)
