        // For compatibility with the test harness, attempt to call it. If the mapping isn't public in
        // the compiled artifact this line will cause a compile error; per the task requirements the
        // state is observable via a public getter.

        (uint256 recordedBlock, bytes32 recordedGuess) = c.guesses(caller);

