pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the attacker address (as an index seed) and the block offset to avoid hard-coding
    function testFuzz_property(uint256 seed, uint256 blockOffset) public {
        // keep domain wide but sensible
        vm.assume(blockOffset < 20); // small offset to keep blockhash available

        // Derive an address for the player from seed (not used as a contract address directly)
        address player = address(uint160(uint256(keccak256(abi.encodePacked(seed, "player")))));

        // Deploy a helper that will accept payments and allow us to be the recipient for transfer
        Receiver rec = new Receiver();

        // Fund the helper so it can act as msg.sender when locking in guesses
        vm.deal(address(rec), 5 ether);

        // The contract C's constructor requires exactly 1 ether
        // We need the contract to have less than 2 ether to trigger mutant revert when paying winners
        // Deploy already done in setUp(); top-up c to exactly 1 ether (constructor required that)
        // But setUp used new C() verbatim (per instructions). Ensure c has 1 ether balance (it should from ctor)

        // Now, from the helper, call lockInGuess by impersonating it and sending 1 ether
        bytes32 guess = bytes32(uint256(1));
        vm.prank(address(rec));
        rec.callLockInGuess(address(c), guess);

        // advance one block so settle's required block.number > guesses[msg.sender].block can be satisfied
        // We need to call settle at block > stored block (stored was block.number + 1 at lock). So mine two blocks.
        vm.roll(block.number + 2 + blockOffset);

        // The helper will be the caller of settle; it will receive the transfer if it 'wins'.
        // To make it a winning guess, we need rec to recreate the same answer as c computes.
        // The answer uses keccak256(abi.encodePacked(blockhash(guesses[msg.sender].block))) where guesses[msg].block was set
        // to lockBlock = lockBlockNumber + 1. We can read that by having the helper compute expected answer using blockhash of that block.
        // But in tests we can simply call settle and observe whether it reverts or not.

        bool ok;
        // call settle as the helper (it was the one who locked)
        vm.prank(address(rec));
        try rec.callSettle(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct contract, settle never reverts on a winning settle call even when contract balance < 2 ether
        // Practically: original C will not revert here; the mutant can revert when transfer(2 ether) is attempted but contract lacks funds.
        assertTrue(ok);
    }
}

// Minimal helper that acts as an external player; it will lock a guess and call settle.
contract Receiver {
    // store last locked block for reference if needed
    function callLockInGuess(address target, bytes32 h) external payable {
        // call lockInGuess on C, forwarding 1 ether from this contract's balance
        // Use low-level call to preserve interface independence
        (bool s,) = target.call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", h));
        require(s);
    }

    function callSettle(address target) external {
        // call settle on C
        (bool s,) = target.call(abi.encodeWithSignature("settle()"));
        if (!s) revert("settle failed");
    }

    receive() external payable {}
}

