        // Advance to targetBlock so blockhash(targetBlock) is available
        vm.roll(targetBlock);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(targetBlock)));

        // Now roll back to startBlock to perform lockInGuess from player's EOA
        vm.roll(startBlock);

